#!/usr/bin/env python3
"""Build the pinned USearch C API plus the small memory ABI adapter using Emscripten."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tarfile
import tempfile
import urllib.request

REVISION = 'a985f77553d2d58d5ef1516eafaae81480bb3c30'
ROOT = Path(__file__).resolve().parents[6]
HERE = Path(__file__).resolve().parent
EXPORTS = ['malloc', 'free', 'index_error', 'index_create', 'index_add_batch', 'index_search', 'index_search_filtered', 'index_score_keys', 'index_size', 'index_remove', 'index_save_size', 'index_save', 'index_load', 'index_destroy']

# Builds the pinned module only when its inputs or generated bytes have changed.
def build(source: Path | None = None) -> None:
    output = HERE.parent.parent / 'resources/usearch.wasm'
    state_file = HERE.parent.parent / '.cache/usearch-build.json'
    signature = hashlib.sha256(
        REVISION.encode() + Path(__file__).read_bytes() + (HERE / 'index.cpp').read_bytes()
    ).hexdigest()
    state = json.loads(state_file.read_text()) if state_file.is_file() else {}
    if source is None and output.is_file() and state == {
        'inputs': signature, 'output': hashlib.sha256(output.read_bytes()).hexdigest(),
    }:
        _publish_example(output)
        print('USearch WASM is up to date')
        return
    source = source or Path(tempfile.gettempdir()) / 'operit-usearch-build' / ('USearch-' + REVISION)
    if not source.exists():
        source.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix='operit-usearch-') as temporary:
            archive = Path(temporary) / 'source.tar.gz'
            urllib.request.urlretrieve('https://codeload.github.com/unum-cloud/USearch/tar.gz/' + REVISION, archive)
            with tarfile.open(archive) as package:
                package.extractall(source.parent, filter='data')
    if (source / '.git').exists():
        actual = subprocess.check_output(['git', '-C', str(source), 'rev-parse', 'HEAD'], text=True).strip()
        if actual != REVISION:
            raise SystemExit('USearch source must be pinned to ' + REVISION)
    compiler = os.environ.get('EMXX') or shutil.which('em++')
    if compiler:
        command = [compiler]
    else:
        managed_compiler = ROOT / '.ci-tools/emsdk/upstream/emscripten/em++.py'
        if not managed_compiler.is_file():
            raise FileNotFoundError('USearch requires Emscripten: install .ci-tools/emsdk or set EMXX to em++.')
        command = [sys.executable, str(managed_compiler)]
    output.parent.mkdir(parents=True, exist_ok=True)
    subprocess.run([*command, str(source / 'c/lib.cpp'), str(HERE / 'index.cpp'), '-I' + str(source / 'include'), '-I' + str(source / 'c'), '-DUSEARCH_USE_NUMKONG=0', '-DUSEARCH_USE_OPENMP=0', '-DNDEBUG', '-std=c++17', '-O3', '-flto', '-msimd128', '--no-entry', '-sSTANDALONE_WASM=1', '-sALLOW_MEMORY_GROWTH=1', '-sFILESYSTEM=0', '-sEXPORTED_FUNCTIONS=' + json.dumps(['_' + name for name in EXPORTS]), '-o', str(output)], check=True)
    state_file.parent.mkdir(parents=True, exist_ok=True)
    state_file.write_text(json.dumps({'inputs': signature, 'output': hashlib.sha256(output.read_bytes()).hexdigest()}))
    _publish_example(output)
    print('Built', output.stat().st_size, 'bytes from', REVISION)


# Refreshes the example's module from the same owner-built binary.
def _publish_example(output: Path) -> None:
    targets = [ROOT / 'plugins/packages/examples/toolpkg_usearch_demo/modules/usearch.wasm']
    for target in targets:
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.is_file() or target.read_bytes() != output.read_bytes():
            shutil.copyfile(output, target)


# Parses the optional pinned source checkout for manual builds.
def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('--source', type=Path, help='Existing checkout of the pinned USearch revision')
    args = parser.parse_args()
    build(args.source)

if __name__ == '__main__':
    main()
